/**
 * dsh-ui-peak-valley browser half — generated by dsh-ui-suite/scripts/build.mjs.
 *
 * One component per package: the runtime below is the same code every suite
 * package carries, so installing this package alone works, and the component
 * mounts under the same failure boundary as the rest of the suite.
 *
 * Edit src/component.js (or the runtime in dsh-ui-copy/src/core), then rerun
 * the build.
 */

/**
 * dsh-ui-copy runtime — the one place where a component gets its services.
 *
 * The suite exists because a dozen UI plugins used to poll the same document
 * with a dozen MutationObservers, each injecting its own <style> and each
 * guessing whether the shipped DOM had already mounted. This runtime gives them
 * one observer, one frame budget, one style registry and one failure boundary:
 *
 *   - `observe(pass)` registers a DOM pass; every registered pass runs in a
 *     single rAF-throttled sweep, and one crashing pass never stops the rest.
 *   - `style(id, css)` registers a sheet by component id, so a sheet can be
 *     replaced without touching the DOM and no sheet is ever written twice.
 *   - `mount(key, factory)` calls a component factory under `try`/`catch`, so a
 *     host upgrade that removes a slot, or a disabled external bundle, disables
 *     one component instead of the whole suite.
 *   - `option(name, fallback)` reads the config the host half injected, which is
 *     the only channel a browser bundle has: a boot-graph row arrives as
 *     `{ id, url, rev }` and `apply(ctx, config)` always sees an empty config.
 *
 * Component contract — a component is a top-level function in the built bundle:
 *
 *     function dshuiComponent_<key>(rt) {
 *       if (rt.config.enabled === false) return
 *       ...
 *     }
 *
 * Components never touch `window.__ModuleLoader__`, never build their own
 * MutationObserver, and never write a literal colour, radius, gap, size,
 * duration or shadow: those live in `lib/styles/tokens.css` as `--dshui-*`.
 */

/**
 * Build the runtime handed to every component.
 *
 * @param env - `{ ctx, require }` from the bundle factory.
 * @param config - the host half's injected `window.__DSHUI_CONFIG__` object.
 */
function dshuiCreateRuntime(env, config) {
  var ctx = env.ctx
  var load = env.require
  // The token contract lives on `body` (see lib/styles/tokens.css), so a token
  // is read there rather than from the document root.
  var root = document.body !== null ? document.body : document.documentElement
  var suiteConfig = isRecord(config) ? config : {}

  /** Component state: key -> `{ enabled, options }`. */
  var components = Object.create(null)

  /** Every DOM pass registered by an enabled component. */
  var passes = []

  /** Owned cleanups, run by `dispose`. */
  var cleanups = []

  /** A frame has been requested but has not run yet. */
  var scheduled = false

  function isRecord(value) {
    return typeof value === 'object' && value !== null && !Array.isArray(value)
  }

  function merge(base, over) {
    var out = {}
    var key
    for (key in base) if (Object.prototype.hasOwnProperty.call(base, key)) out[key] = base[key]
    for (key in over) if (Object.prototype.hasOwnProperty.call(over, key)) out[key] = over[key]
    return out
  }

  /**
   * A component key as the schema spells it: `session-delete` -> `sessionDelete`.
   *
   * Component ids stay hyphenated (they match `<nn>-<key>.js` and the sheet
   * names), while the host schema uses camelCase field names, so every lookup
   * tries both spellings rather than making each component remember which one
   * its block landed under.
   */
  function schemaKeyOf(key) {
    return String(key).replace(/-([a-z0-9])/g, function (_, letter) {
      return letter.toUpperCase()
    })
  }

  /**
   * The config block for one component.
   *
   * Accepts both shapes a config can arrive in — a flat `{ quota: { … } }` map
   * and the same value nested under `components` — and both spellings, because
   * the host half writes camelCase while components name themselves with
   * hyphens.
   */
  function componentConfig(key) {
    var names = [key, schemaKeyOf(key)]
    var found = null
    for (var index = 0; index < names.length; index += 1) {
      if (isRecord(suiteConfig[names[index]])) {
        found = suiteConfig[names[index]]
        break
      }
    }
    var nestedSource = isRecord(suiteConfig.components) ? suiteConfig.components : null
    var nested = null
    if (nestedSource !== null) {
      for (var position = 0; position < names.length; position += 1) {
        if (isRecord(nestedSource[names[position]])) {
          nested = nestedSource[names[position]]
          break
        }
      }
    }
    return merge(nested || {}, found || {})
  }

  function warn(key, message) {
    console.warn('[ui-copy/' + key + '] ' + message)
  }

  function fail(key, error) {
    console.error('[ui-copy/' + key + ']', error)
  }

  function request() {
    if (scheduled) return
    scheduled = true
    requestAnimationFrame(run)
  }

  function run() {
    scheduled = false
    if (document.body === null) return
    var snapshot = passes.slice()
    for (var index = 0; index < snapshot.length; index += 1) {
      var entry = snapshot[index]
      if (entry === undefined) continue
      try {
        entry.pass()
      } catch (error) {
        fail(entry.key, error)
        var position = passes.indexOf(entry)
        if (position !== -1) passes.splice(position, 1)
      }
    }
  }

  function sheetById(id) {
    return document.head.querySelector('style[data-dshui-sheet="' + String(id).replace(/["\\]/g, '\\$&') + '"]')
  }

  function installStyle(id, css) {
    var existing = sheetById(id)
    if (existing !== null) {
      existing.textContent = css
      return function () {
        if (existing.parentNode !== null) existing.parentNode.removeChild(existing)
      }
    }
    var style = document.createElement('style')
    style.setAttribute('data-dshui-sheet', id)
    style.textContent = css
    document.head.appendChild(style)
    return function () {
      if (style.parentNode !== null) style.parentNode.removeChild(style)
    }
  }

  function requireExternal(name) {
    try {
      return load(name)
    } catch (error) {
      fail('bundle', 'cannot load "' + name + '": ' + String((error && error.message) || error))
      return null
    }
  }

  /** The object handed to one component factory. */
  function componentApi(key, options) {
    return {
      /* ---- identity -------------------------------------------------- */
      key: key,
      ctx: ctx,
      suite: suiteConfig,

      /* ---- configuration --------------------------------------------- */
      /** This component's own block. `enabled` is already honoured by `mount`. */
      config: options,
      option: function (name, fallback) {
        var value = options[name]
        return value === undefined ? fallback : value
      },
      /** Another component's state, for components that depend on a sibling. */
      component: function (other) {
        return components[other] || { enabled: false, options: {} }
      },
      /** The current theme name, read from the same attribute the host themes on. */
      theme: function () {
        return document.body !== null && document.body.hasAttribute('data-ds-dark-theme') ? 'dark' : 'light'
      },

      /* ---- host services --------------------------------------------- */
      /** An external package, or `null` when it is not in this boot graph. */
      require: requireExternal,
      /** Run a host effect, or run the body directly when the seam is absent. */
      effect: function (body, label) {
        try {
          if (ctx && typeof ctx.effect === 'function') return ctx.effect(body, label || key)
        } catch (error) {
          fail(key, error)
          return undefined
        }
        try {
          return body()
        } catch (error) {
          fail(key, error)
          return undefined
        }
      },

      /* ---- document --------------------------------------------------- */
      /** Register a DOM pass; returns an unsubscribe function. */
      observe: function (pass) {
        var entry = { key: key, pass: pass }
        passes.push(entry)
        if (document.body !== null) request()
        return function () {
          var index = passes.indexOf(entry)
          if (index !== -1) passes.splice(index, 1)
        }
      },
      /** Ask for one sweep on the next frame. */
      schedule: request,
      /** Install or replace a sheet scoped to this component. */
      style: function (id, css) {
        return installStyle(key + '/' + id, css)
      },
      /** Current text of one of this component's sheets. */
      styleText: function (id) {
        var style = sheetById(key + '/' + id)
        return style === null ? '' : style.textContent
      },
      /** A token's computed value; components should prefer the CSS variable. */
      token: function (name, fallback) {
        try {
          var scope = document.body !== null ? document.body : root
          var value = getComputedStyle(scope).getPropertyValue(name).trim()
          if (value !== '') return value
        } catch (error) {
          fail(key, error)
        }
        return fallback === undefined ? '' : fallback
      },

      /* ---- diagnostics ------------------------------------------------ */
      log: function (message) {
        console.info('[ui-copy/' + key + '] ' + message)
      },
      warn: function (message) {
        warn(key, message)
      },
      error: function (error) {
        fail(key, error)
      },
    }
  }

  /**
   * Register a component and hand it the runtime.
   *
   * Enabled is the config's `enabled` when it is a boolean and `true` when the
   * profile says nothing, so a component that ships enabled keeps working after
   * an upgrade that adds a sibling and the user turns things off one by one.
   */
  function mount(key, factory) {
    var options = componentConfig(key)
    var record = {
      key: key,
      enabled: options.enabled === false ? false : true,
      options: options,
    }
    components[key] = record
    if (!record.enabled) return
    if (typeof factory !== 'function') {
      warn(key, 'no factory for this component')
      return
    }
    try {
      factory(componentApi(key, options))
    } catch (error) {
      record.enabled = false
      fail(key, error)
    }
  }

  var observer = null
  if (typeof MutationObserver === 'function') {
    observer = new MutationObserver(request)
    var start = function () {
      if (document.body === null) return
      // No `attributes`: React churns attributes constantly, and a component
      // that writes an attribute from a pass would re-enter itself through the
      // observer. Every surface this suite patches is created or replaced as a
      // node, so childList plus characterData is the whole trigger set.
      observer.observe(document.body, { childList: true, subtree: true, characterData: true })
      request()
    }
    if (document.body !== null) start()
    else document.addEventListener('DOMContentLoaded', start, { once: true })
    cleanups.push(function () {
      observer.disconnect()
    })
  }

  /** Remove every pass, sheet and observer this runtime owns. */
  function dispose() {
    passes.length = 0
    for (var index = 0; index < cleanups.length; index += 1) {
      try {
        cleanups[index]()
      } catch (error) {
        /* a failed cleanup must not stop the rest */
      }
    }
    cleanups.length = 0
  }

  var base = componentApi('runtime', {})
  return {
    ctx: ctx,
    config: suiteConfig,
    require: requireExternal,
    mount: mount,
    component: base.component,
    observe: base.observe,
    schedule: base.schedule,
    style: base.style,
    token: base.token,
    theme: base.theme,
    dispose: dispose,
  }
}

/* ---- component -------------------------------------------------------- */

/**
 * Sidebar-foot peak/valley hint.
 *
 * Renders as one `sidebar.footer.action` entry — the slot the sidebar declares
 * for "optional actions beside Settings" — so the column owns the placement,
 * hands the entry the column state (`wide`) and the bound translator, and this
 * component owns nothing but its own row. In the 56px rail there is no room for
 * a sentence, so it renders nothing at all.
 *
 * The rule, as the API bills it:
 *
 *   - peak: Monday to Friday, 09:00–12:00 and 14:00–18:00 Beijing time, on days
 *     that are not a public holiday;
 *   - valley: every other hour, including all of Saturday and Sunday and all of
 *     a public holiday, at any hour.
 *
 * Beijing is a fixed +08:00 offset, so the clock is arithmetic on the epoch
 * rather than a time zone lookup, and the hint reads the same on a machine in
 * any locale.
 *
 * The switch scan walks Beijing's own hour boundaries — 00:00, 09:00, 12:00,
 * 14:00, 18:00 — forward until the verdict flips, which covers a nine-day
 * holiday run with room to spare. The countdown ticks once a second; the label
 * itself only changes at a switch.
 *
 * Holiday dates are the one part a clock cannot derive. The suite's host half
 * serves them on {@link HOLIDAY_ROUTE}; this half starts on
 * {@link FALLBACK_HOLIDAYS}, so the first paint is already right, then adopts
 * the route's answer when it arrives. A route that fails or answers empty
 * leaves the fallback in place: that is the only path that can go stale, and it
 * only happens while the source is unreachable.
 *
 * Two packages come from outside this bundle. React is required for the row
 * itself; the primitives package only supplies the optional tooltip, so its
 * absence degrades to the plain row instead of disabling the component.
 */
function dshuiComponent_peak_valley(rt) {
  const React = rt.require('react')
  if (React === null) {
    rt.warn('react is not in this boot graph; the peak-valley hint is skipped')
    return
  }
  const h = React.createElement

  /**
   * The primitives package, when this boot graph carries it.
   *
   * `rt.require` answers null for a package the graph does not carry, and a
   * release may drop the export, so both are checked before use.
   */
  const primitives = rt.require('@deepseek-ai/dsh-client-ui-primitives')

  /**
   * The tooltip, or null.
   *
   * Null is the documented fallback: the row is then plain text whose `title`
   * carries the very sentence the tooltip would have shown, so the rule is
   * still reachable — only the styled bubble is gone.
   */
  const Tooltip = primitives !== null && typeof primitives === 'object' ? primitives.Tooltip : null

  /** Locale namespace for the label and the rule sentence; also the footer entry's `locale`. */
  const NS = 'peak-valley-hint'

  /** The sidebar's list of optional actions beside Settings. */
  const FOOTER_SLOT = 'sidebar.footer.action'

  /** The suite host half's holiday route; the hint prefers it over the baked-in list. */
  const HOLIDAY_ROUTE = '/dsh-ui-copy/peak-valley/holidays.json'

  /** Beijing's fixed offset; the billing clock is UTC+8 the year round. */
  const BEIJING_OFFSET_MS = 8 * 3600 * 1000

  const HOUR_MS = 3600000
  const DAY_MS = 86400000

  /**
   * Peak windows in Beijing hours, half-open: a window runs from `start` up to
   * but not including `end`.
   */
  const PEAK_HOURS = [
    [9, 12],
    [14, 18],
  ]

  /** The only Beijing hours a window can start or end on. */
  const SWITCH_HOURS = [0, 9, 12, 14, 18]

  /** Days the switch scan looks ahead: the longest holiday run is nine days. */
  const SCAN_DAYS = 12

  /**
   * Leave dates baked in for the case the host route cannot answer.
   *
   * Make-up workdays need no entry: they fall on weekends, which the weekend
   * rule already bills as valley.
   *
   * This list does not have to keep up with the calendar. The route is the
   * source of truth and follows each year's notice on its own; these dates only
   * decide the hint while the network or the source is down.
   */
  const FALLBACK_HOLIDAYS = new Set([
    '2026-01-01', '2026-01-02', '2026-01-03',
    '2026-02-15', '2026-02-16', '2026-02-17', '2026-02-18', '2026-02-19',
    '2026-02-20', '2026-02-21', '2026-02-22', '2026-02-23',
    '2026-04-04', '2026-04-05', '2026-04-06',
    '2026-05-01', '2026-05-02', '2026-05-03', '2026-05-04', '2026-05-05',
    '2026-06-19', '2026-06-20', '2026-06-21',
    '2026-09-25', '2026-09-26', '2026-09-27',
    '2026-10-01', '2026-10-02', '2026-10-03', '2026-10-04',
    '2026-10-05', '2026-10-06', '2026-10-07',
  ])

  /** Simplified Chinese dictionary (the key-set source of truth). */
  const zh = {
    peak: '高峰时段',
    valley: '低谷时段',
    rule: '高峰：周一至周五 09:00–12:00、14:00–18:00（中国法定节假日除外）；低谷：其余全部时段，含周末与法定节假日全天。时间均为北京时间。',
  }

  /** English dictionary, checked complete against the zh key set. */
  const en = {
    peak: 'Peak hours',
    valley: 'Off-peak hours',
    rule: 'Peak: Monday to Friday 09:00–12:00 and 14:00–18:00 Beijing time, excluding Chinese public holidays. Off-peak: every other hour, including all weekend and holiday hours.',
  }

  /**
   * The component's stylesheet, registered through `rt.style`.
   *
   * `margin-left: auto` pushes the row to the far end of the foot, so it sits
   * opposite the panel buttons whatever else the foot holds. Peak and valley
   * take their colour from the danger and success roles (the red and green the
   * shipped pricing surfaces use), and the countdown stays in the quieter text
   * tone. The row's 22px line box and the dot's 6px size are geometry rather
   * than visual language, and they are what lines the row up with the Settings
   * button beside it.
   */
  const STYLESHEET = `
.dsh-pv-hint {
  box-sizing: border-box;
  flex: none;
  display: flex;
  align-items: center;
  gap: var(--dshui-space-2);
  margin-left: auto;
  padding: 0 var(--dshui-space-5) 0 var(--dshui-space-2);
  font-size: var(--dshui-text-size-sm);
  line-height: 22px;
  white-space: nowrap;
  user-select: none;
  cursor: default;
}
.dsh-pv-hint[data-peak='true'] { color: var(--dshui-danger); }
.dsh-pv-hint[data-peak='false'] { color: var(--dshui-success); }
.dsh-pv-dot {
  flex: none;
  width: 6px;
  height: 6px;
  border-radius: var(--dshui-radius-circle);
  background: currentColor;
}
.dsh-pv-count {
  color: var(--dshui-text-tertiary, var(--dshui-text-secondary));
  font-variant-numeric: tabular-nums;
}
`

  /**
   * Beijing calendar fields for an instant.
   *
   * Shifting the epoch and reading it back as UTC is what makes the calendar
   * day, the weekday and the hour all come out in Beijing terms on a machine
   * set to any zone.
   *
   * @param ms - epoch milliseconds.
   * @returns the Beijing date string, weekday (0 = Sunday) and hour.
   */
  function beijing(ms) {
    const shifted = new Date(ms + BEIJING_OFFSET_MS)
    return {
      date: shifted.toISOString().slice(0, 10),
      weekday: shifted.getUTCDay(),
      hour: shifted.getUTCHours(),
    }
  }

  /**
   * Whether an instant bills at the peak price.
   *
   * @param ms - epoch milliseconds.
   * @param holidays - the leave dates in force.
   * @returns true inside a peak window on a working day.
   */
  function isPeak(ms, holidays) {
    const { date, weekday, hour } = beijing(ms)
    if (weekday === 0 || weekday === 6) return false
    if (holidays.has(date)) return false
    return PEAK_HOURS.some(([start, end]) => hour >= start && hour < end)
  }

  /**
   * The next instant the verdict flips.
   *
   * Only the five hour boundaries can switch it, so the scan walks those in
   * Beijing order rather than stepping minute by minute.
   *
   * @param ms - epoch milliseconds.
   * @param holidays - the leave dates in force.
   * @returns epoch milliseconds of the switch, or null when none is in range.
   */
  function nextSwitchAt(ms, holidays) {
    const current = isPeak(ms, holidays)
    // Beijing midnight of the current day, expressed in the shifted frame.
    const midnight = Math.floor((ms + BEIJING_OFFSET_MS) / DAY_MS) * DAY_MS
    for (let day = 0; day <= SCAN_DAYS; day += 1) {
      for (const hour of SWITCH_HOURS) {
        const candidate = midnight + day * DAY_MS + hour * HOUR_MS - BEIJING_OFFSET_MS
        if (candidate <= ms + 1000) continue
        if (isPeak(candidate, holidays) !== current) return candidate
      }
    }
    return null
  }

  /**
   * Format a remaining span as HH:MM:SS.
   *
   * Hours are not wrapped at 24: a Friday evening runs three days into the
   * weekend, and the countdown says so.
   *
   * @param ms - remaining milliseconds.
   * @returns the formatted span.
   */
  function countdownText(ms) {
    const total = Math.max(0, Math.floor(ms / 1000))
    const pad = (value) => String(value).padStart(2, '0')
    return `${pad(Math.floor(total / 3600))}:${pad(Math.floor((total % 3600) / 60))}:${pad(total % 60)}`
  }

  /**
   * The wall clock the hint renders from, re-read once a second.
   *
   * @returns the current epoch milliseconds.
   */
  function useNow() {
    const [now, setNow] = React.useState(() => Date.now())
    React.useEffect(() => {
      const timer = window.setInterval(() => setNow(Date.now()), 1000)
      return () => window.clearInterval(timer)
    }, [])
    return now
  }

  /**
   * The holiday calendar the hint judges with, asked for once per page.
   *
   * @returns the leave dates in force.
   */
  function useHolidays() {
    const [holidays, setHolidays] = React.useState(() => FALLBACK_HOLIDAYS)
    React.useEffect(() => {
      let alive = true
      fetch(HOLIDAY_ROUTE, { headers: { accept: 'application/json' } })
        .then((response) => (response.ok ? response.json() : null))
        .then((body) => {
          if (!alive) return
          if (body === null || body.ok !== true || !Array.isArray(body.holidays) || body.holidays.length === 0) return
          setHolidays(new Set(body.holidays))
        })
        .catch(() => {})
      return () => {
        alive = false
      }
    }, [])
    return holidays
  }

  /**
   * The hint itself.
   *
   * The tooltip is the only part that depends on the primitives package: with
   * it the rule sentence lives in a bubble, without it the same sentence rides
   * on the row's native `title`.
   *
   * @param props - the sidebar's owner share (`wide`) and the bound translator.
   * @returns the row, or null while the column is a rail.
   */
  function PeakValleyHint({ wide, t }) {
    const now = useNow()
    const holidays = useHolidays()
    if (!wide) return null
    const peak = isPeak(now, holidays)
    const next = nextSwitchAt(now, holidays)
    const label = peak ? t('peak') : t('valley')
    const remaining = next === null ? null : countdownText(next - now)
    const rule = t('rule')
    const row = h(
      'div',
      {
        className: 'dsh-pv-hint',
        'data-peak': peak ? 'true' : 'false',
        'aria-label': remaining === null ? label : `${label} ${remaining}`,
        title: typeof Tooltip === 'function' ? undefined : rule,
      },
      h('span', { className: 'dsh-pv-dot', key: 'dot', 'aria-hidden': 'true' }),
      h('span', { className: 'dsh-pv-label', key: 'label' }, label),
      remaining === null ? null : h('span', { className: 'dsh-pv-count', key: 'count' }, remaining),
    )
    if (typeof Tooltip !== 'function') return row
    return h(Tooltip, { label: rule, delayMs: 400 }, row)
  }

  /**
   * Component body: stylesheet, dictionaries, then the footer entry.
   *
   * The sheet goes up front so the first paint of the slot is already styled.
   * Both services are waited for through one `ctx.inject`, so a host without the
   * sidebar's slot or without a locale service disables this component and
   * touches nothing else in the suite.
   *
   * @param ctx - the client root context.
   */
  function install(ctx) {
    rt.effect(() => rt.style('peak-valley', STYLESHEET), 'ui-copy/peak-valley: stylesheet')

    ctx.inject(['slots', 'locale'], (scope) => {
      scope.effect(() => scope.locale.register(NS, { zh, en }), 'ui-copy/peak-valley: dictionaries')
      scope.slots.inject(FOOTER_SLOT, () =>
        scope.slots.register(
          {
            name: FOOTER_SLOT,
            id: 'peak-valley-hint',
            order: 20,
            locale: NS,
          },
          PeakValleyHint,
        ),
      )
    })
  }

  install(rt.ctx)
}

/* ---- entry ------------------------------------------------------------ */

